library(shiny)
b <- readRDS('bundle.rds')
ages <- c('18–24','25–29','30–34','35–39','40–44','45–49','50–54','55–59','60–64','65–69','70–74','75–79','80+')
fmt <- function(x) format(x,big.mark=',',scientific=FALSE,trim=TRUE)
pct <- function(x) sprintf('%.1f%%',100*x)
card <- function(label,value,detail) div(class='stat',div(class='stat-label',label),div(class='stat-value',value),div(class='muted',detail))
yesno <- function(id,label) selectInput(id,label,c('No'=0,'Yes'=1),width='100%')
ui <- fluidPage(
 tags$head(tags$title('CardioScope | Heart attack analysis'),tags$style(HTML(" 
