 div(class='stats',card('Survey responses',fmt(b$raw_rows),'CDC BRFSS · 2023'),card('Eligible outcomes',fmt(b$n),'Known yes / no responses'),card('Test ROC AUC',sprintf('%.3f',b$metrics['AUC']),'Untouched 20% holdout'),card('Sample prevalence',pct(b$prevalence),'Unweighted · history of heart attack')),
