 uiOutput('dash_cards'),fluidRow(column(6,div(class='panel-card',h3('Age distribution'),plotOutput('dash_ageplot',height='280px'))),column(6,div(class='panel-card',h3('Predicted probability distribution'),plotOutput('dash_hist',height='280px')))),
 fluidRow(column(6,div(class='panel-card',h3('Health characteristics'),plotOutput('dash_factors',height='280px'))),column(6,div(class='panel-card',h3('Test performance at your threshold'),tableOutput('dash_metrics'),p(class='section-note','Threshold exploration is descriptive. The original held-out evaluation used a threshold selected on validation only.'),textOutput('dash_updated'))))),
 tabPanel('Profile explorer',value='profile',fluidRow(
 column(7,div(class='panel-card',h3('Explore a health profile'),p(class='section-note','Choose a hypothetical profile. The model estimates association with an existing history, with no future time horizon.'),
