 column(5,div(class='result',div(class='eyebrow',style='color:#91d6ca','Model output'),h3('Estimated history probability'),textOutput('probability',container=function(...) div(class='probability',...)),p('Probability of a “yes” response for a similar survey profile.'),div(class='muted',textOutput('comparison'))),
 div(class='panel-card',h3('Read the estimate correctly'),p(class='section-note','This is an educational statistical association. It does not estimate your chance of a future heart attack, diagnose disease, or determine treatment.'),div(class='note','Do not use this app to assess symptoms or make medical decisions.'),downloadButton('profile_download','Download profile estimate')))),
 fluidRow(column(6,div(class='panel-card',h3('Your profile across age groups'),p(class='section-note','Hold the other inputs fixed and vary age category. This is a model scenario, not a forecast.'),plotOutput('profile_age',height='270px'))),column(6,div(class='panel-card',h3('How the estimate varies with BMI'),p(class='section-note','Hold the other inputs fixed and vary BMI. These associations do not measure effects of weight changes.'),plotOutput('profile_bmi',height='270px')))),
 fluidRow(column(7,div(class='panel-card',h3('What contributes to this estimate?'),p(class='section-note','Fitted contributions on the log-odds scale relative to the model intercept. These are model terms, not causal effects.'),plotOutput('profile_terms',height='310px'))),column(5,div(class='panel-card',h3('Your estimate in the survey context'),plotOutput('profile_context',height='310px'),p(class='section-note','Distribution of fitted history probabilities across all eligible survey profiles. The marker shows your current input profile.'))))),
 tabPanel('Dataset & patterns',value='data',fluidRow(column(8,div(class='panel-card',h3('Heart attack history across age groups'),plotOutput('ageplot',height='330px'),p(class='section-note','Observed sample proportions after predictor imputation. Bars are unweighted; these are not national prevalence estimates.')),div(class='panel-card',h3('Explore the survey sample'),fluidRow(column(6,selectInput('filter_sex','Filter survey sex',c('All','Female','Male'))),column(6,selectInput('filter_outcome','Filter outcome',c('All','Reported heart attack','No reported heart attack')))),textOutput('filtered_count'),tableOutput('sample_table'),downloadButton('data_download','Download filtered analysis data'))),column(4,div(class='panel-card',h3('A large, real-world dataset'),p(class='section-note','BRFSS is CDC’s annual telephone survey of noninstitutionalized adults. The 2023 public file contains 433,323 records and 345 variables, from 48 states, DC, Guam, Puerto Rico and the US Virgin Islands. Kentucky and Pennsylvania are excluded.'),tags$a(href='https://www.cdc.gov/brfss/annual_data/annual_2023.html',target='_blank','Source & CDC codebook ↗'),hr(),h4('Outcome'),p(class='section-note','CVDINFR4: ever told you had a heart attack, also called a myocardial infarction? Yes = 1; no = 2. Unknown/refused/missing outcomes are excluded.'),textOutput('counts'),h4('Missing predictors'),p(class='section-note','Training-set median imputation. Missingness and fitted medians are visible below.'),tableOutput('missing_table')))),div(class='panel-card',h3('Variable dictionary'),tableOutput('dictionary'))),
 tabPanel('Model evaluation',value='evaluation',fluidRow(column(6,div(class='panel-card',h3('Discrimination · ROC curve'),plotOutput('rocplot',height='300px'))),column(6,div(class='panel-card',h3('Calibration · predicted vs observed'),plotOutput('calplot',height='300px')))),fluidRow(column(5,div(class='panel-card',h3('Held-out test metrics'),tableOutput('metrics_table'),p(class='section-note',sprintf('Threshold %.3f selected on validation using Youden’s J. Test data were not used to choose the threshold.',b$threshold)),downloadButton('metrics_download','Download metrics'))),column(7,div(class='panel-card',h3('Confusion matrix'),tableOutput('confusion'),p(class='section-note','A low-prevalence outcome makes accuracy alone misleading. Inspect sensitivity, specificity, precision and the constant-probability Brier baseline.'),tableOutput('baseline_table'),h4('Subgroup performance'),tableOutput('subgroups'))))),
 tabPanel('Methods & limitations',value='methods',fluidRow(column(7,div(class='panel-card',h3('A reproducible R workflow'),tags$ol(tags$li('Download the official CDC SAS transport file; retain ten documented columns.'),tags$li('Exclude unknown outcomes. Recode eight predictors; mark invalid and unknown values as missing.'),tags$li('Stratify a seeded 60% / 20% / 20% train, validation, test split.'),tags$li('Impute predictor medians from training only. Fit logistic regression with quadratic age category and BMI terms.'),tags$li('Choose classification threshold on validation only. Report untouched test AUC, Brier, calibration and classification metrics.')),textOutput('split_counts'),hr(),h4('Fitted coefficients'),tableOutput('effects'),p(class='section-note','Odds ratios are conditional associations. Squared terms mean the age and BMI linear coefficients cannot be interpreted independently.'))),column(5,div(class='panel-card',h3('What the model cannot tell you'),tags$ul(tags$li('No future incidence labels or prediction horizon.'),tags$li('Self-report, recall bias and survivorship bias affect the target.'),tags$li('Post-diagnosis behavior may affect predictors; associations are not causal.'),tags$li('Unweighted sample model does not account for complex survey design.'),tags$li('Median imputation can distort associations and underestimate uncertainty.'),tags$li('Internal random split only; no external or temporal validation.'),tags$li('US adult survey patterns may not generalize to other populations.')),h4('Scope & reproducibility'),p(class='section-note','One transparent baseline model, not a clinically validated risk score. analysis.R reproduces all metrics from the included source-column CSV. Survey weights are retained for future survey-aware work but not used by this model.'),tags$a(href='https://github.com/akshithaguthupa18-ctrl/heart-attack-risk-shiny',target='_blank','View project on GitHub ↗')))))
 ),div(class='footer',span('CardioScope · CDC BRFSS 2023'),span('Built with R + Shiny · Educational research only'))
)
server <- function(input,output,session) {
 all_predictions <- as.numeric(predict(b$model,b$data,type='response'))
 cohort_index <- reactive({req(input$dash_age); ix<-b$data$age>=input$dash_age[1] & b$data$age<=input$dash_age[2]; if(input$dash_sex!='All') ix<-ix & b$data$male==as.integer(input$dash_sex=='Male'); ix})
 output$dash_cards <- renderUI({ix<-cohort_index(); req(any(ix)); div(class='stats',card('Cohort responses',fmt(sum(ix)),'Filters applied instantly'),card('Observed history',pct(mean(b$data$heart_attack[ix])),'Unweighted sample proportion'),card('Mean model estimate',pct(mean(all_predictions[ix])),'History probability'),card('Test responses',fmt(sum(ix & b$split==3)),'Held-out subset'))})
 output$dash_ageplot <- renderPlot({style_plot();z<-table(factor(b$data$age[cohort_index()],levels=1:13));barplot(z,names.arg=ages,las=2,col='#239c91',border=NA,ylab='Responses')})
 output$dash_hist <- renderPlot({style_plot();x<-all_predictions[cohort_index()];validate(need(length(x)>0,'No responses match.'));hist(x,breaks=30,col='#239c91',border='white',xlab='Estimated history probability',main='');abline(v=input$dash_threshold,col='#db9855',lwd=2,lty=2)})
 output$dash_factors <- renderPlot({style_plot();z<-b$data[cohort_index(),c('hypertension','cholesterol','diabetes','smoker','inactive')];barplot(colMeans(z)*100,names.arg=c('High BP','Cholesterol','Diabetes','Smoking','Inactive'),col='#239c91',border=NA,ylab='Cohort share (%)',las=2)})
 output$dash_metrics <- renderTable({ix<-cohort_index() & b$split==3;y<-b$data$heart_attack[ix];p<-all_predictions[ix];t<-input$dash_threshold;validate(need(length(y)>0 && length(unique(y))==2,'Choose a cohort containing both outcomes.'));tp<-sum(y==1 & p>=t);fp<-sum(y==0 & p>=t);tn<-sum(y==0 & p<t);fn<-sum(y==1 & p<t);data.frame(Metric=c('Sensitivity','Specificity','Precision','Accuracy','True positives','False positives'),Value=c(pct(tp/(tp+fn)),pct(tn/(tn+fp)),if(tp+fp>0)pct(tp/(tp+fp)) else 'No positive predictions',pct((tp+tn)/length(y)),fmt(tp),fmt(fp)))})
 output$dash_updated <- renderText({cohort_index();input$dash_threshold;paste('Recalculated',format(Sys.time(),'%H:%M:%S'),'· session time')})
 profile <- reactive({
   req(is.finite(input$bmi)); validate(need(input$bmi>=12 && input$bmi<=80,'BMI must be between 12 and 80.'))
   data.frame(age=as.numeric(input$age),male=as.numeric(input$male),bmi=input$bmi,hypertension=as.numeric(input$hypertension),cholesterol=as.numeric(input$cholesterol),diabetes=as.numeric(input$diabetes),smoker=as.numeric(input$smoker),inactive=as.numeric(input$inactive))
 })
 prediction <- reactive(as.numeric(predict(b$model,profile(),type='response')))
 output$probability <- renderText(pct(prediction()))
 output$comparison <- renderText(sprintf('Sample reference: %s · This is not a future-risk estimate.',pct(b$prevalence)))
 output$profile_age <- renderPlot({style_plot();d<-profile()[rep(1,13),];d$age<-1:13;p<-predict(b$model,d,type='response');plot(1:13,p*100,type='b',pch=19,lwd=3,col='#008c82',xaxt='n',xlab='Age category',ylab='History probability (%)');axis(1,at=1:13,labels=ages,las=2,cex.axis=.8);points(profile()$age,prediction()*100,pch=21,bg='#dfad65',col='#143d43',cex=1.7)})
 output$profile_bmi <- renderPlot({style_plot();v<-seq(12,60,length.out=120);d<-profile()[rep(1,length(v)),];d$bmi<-v;p<-predict(b$model,d,type='response');plot(v,p*100,type='l',lwd=3,col='#008c82',xlab='BMI (kg/m²)',ylab='History probability (%)');points(profile()$bmi,prediction()*100,pch=21,bg='#dfad65',col='#143d43',cex=1.7)})
 output$profile_terms <- renderPlot({par(mar=c(4,10,1,1));x<-model.matrix(delete.response(terms(b$model)),profile());v<-as.numeric(x[1,-1])*coef(b$model)[-1];names(v)<-names(coef(b$model))[-1];v<-sort(v);barplot(v,horiz=TRUE,las=1,col=ifelse(v>=0,'#239c91','#d8ae73'),border=NA,xlab='Contribution to model log-odds');abline(v=0,col='#54717b')})
 output$profile_context <- renderPlot({style_plot();hist(all_predictions,breaks=40,col='#d1e9e5',border='white',main='',xlab='Model probability',ylab='Survey responses');abline(v=prediction(),col='#007f78',lwd=3);legend('topright',legend=paste('Your profile:',pct(prediction())),col='#007f78',lwd=3,bty='n')})
 output$profile_download <- downloadHandler(filename=function() 'profile-estimate.csv',content=function(file) write.csv(cbind(profile(),history_probability=prediction(),interpretation='Research estimate of self-reported history; not future risk'),file,row.names=FALSE))
 style_plot <- function() par(mar=c(5,4,2,1),col.axis='#60777f',col.lab='#304e59',fg='#dce6e7',family='sans')
 output$ageplot <- renderPlot({style_plot(); z<-b$age_summary; barplot(z$rate*100,names.arg=ages,col='#239c91',border=NA,las=2,ylab='Reported heart attack (%)');box(bty='l')})
 filtered <- reactive({d<-b$data;if(input$filter_sex!='All')d<-d[d$male==as.integer(input$filter_sex=='Male'),];if(input$filter_outcome!='All')d<-d[d$heart_attack==as.integer(input$filter_outcome=='Reported heart attack'),];d})
 output$filtered_count <- renderText(paste(fmt(nrow(filtered())),'responses match. Showing the first 10; predictors are imputed analysis values.'))
 output$sample_table <- renderTable(head(filtered()[,c('heart_attack','age','male','bmi','hypertension','cholesterol','diabetes','smoker','inactive')],10))
 output$data_download <- downloadHandler(filename=function() 'brfss-analysis-filtered.csv',content=function(file) write.csv(filtered(),file,row.names=FALSE))
 output$counts <- renderText(sprintf('%s known outcomes; %s excluded.',fmt(b$n),fmt(b$excluded)))
 output$split_counts <- renderText(sprintf('Train %s · Validation %s · Test %s · Seed 20261105',fmt(b$train),fmt(b$validation),fmt(b$test)))
 output$missing_table <- renderTable(data.frame(Predictor=names(b$missing),Missing=as.integer(b$missing),Median=round(b$medians,2)))
 output$dictionary <- renderTable(data.frame(Variable=c('CVDINFR4','_AGEG5YR','SEXVAR','_BMI5','BPHIGH6','TOLDHI3','DIABETE4','_SMOKER3','EXERANY2','_LLCPWT'),Meaning=c('Reported history of heart attack (outcome)','13 ordered age groups: 18–24 through 80+','Survey sex: male / female','BMI scaled by 100 in raw file','High blood pressure diagnosis','High cholesterol diagnosis','Diabetes diagnosis','Current smoker status','Any leisure-time exercise in past month','Final survey weight (retained, not used)'),Recode=c('1=yes, 2=no; others excluded','1–13 valid; 14 unknown','1=male, 2=female','Divide by 100; keep BMI 12–80','1=yes; 2/3/4=no','1=yes, 2=no','1=yes; 2/3/4=no','1/2=current; 3/4=not current','1=active; 2=inactive','Original numeric weight')))
 output$rocplot <- renderPlot({style_plot();plot(b$roc[,1],b$roc[,2],type='l',lwd=3,col='#008c82',xlab='False positive rate',ylab='True positive rate',xlim=c(0,1),ylim=c(0,1));abline(0,1,lty=2,col='#b6c6c9');legend('bottomright',legend=sprintf('AUC %.3f',b$metrics['AUC']),bty='n')})
 output$calplot <- renderPlot({style_plot();z<-b$calibration;lim<-c(0,max(z$predicted,z$observed)*1.1);plot(z$predicted,z$observed,pch=19,col='#008c82',type='b',lwd=2,xlab='Mean predicted probability',ylab='Observed proportion',xlim=lim,ylim=lim);abline(0,1,lty=2,col='#b6c6c9')})
 output$metrics_table <- renderTable(data.frame(Metric=names(b$metrics)[1:6],Value=round(b$metrics[1:6],4)),rownames=FALSE,digits=4)
 output$confusion <- renderTable(data.frame('Actual'=c('Reported heart attack','No reported heart attack'),'Predicted positive'=c(b$metrics['TP'],b$metrics['FP']),'Predicted negative'=c(b$metrics['FN'],b$metrics['TN']),check.names=FALSE))
 output$baseline_table <- renderTable(data.frame(Model=c('Logistic regression','Constant training prevalence'),Brier=round(c(b$metrics['Brier'],b$baseline_brier),4)),digits=4)
 output$subgroups <- renderTable(transform(b$groups[b$groups$group=='male',],value=ifelse(value==1,'Male','Female')),digits=3)
 output$effects <- renderTable(b$effects,digits=4)
 output$metrics_download <- downloadHandler(filename=function()'metrics.csv',content=function(file)write.csv(data.frame(metric=names(b$metrics),value=b$metrics),file,row.names=FALSE))
}
shinyApp(ui,server)
